import{_ as a}from"./chunks/architecture.Cs8uKTTN.js";import{_ as e,o as n,c as i,a2 as p}from"./chunks/framework.CHeM0PsO.js";const m=JSON.parse('{"title":"개념","description":"","frontmatter":{},"headers":[],"relativePath":"ko/concepts/overview.md","filePath":"ko/concepts/overview.md","lastUpdated":1784903584000}'),t={name:"ko/concepts/overview.md"};function o(l,s,c,r,d,h){return n(),i("div",null,[...s[0]||(s[0]=[p('<h1 id="개념" tabindex="-1">개념 <a class="header-anchor" href="#개념" aria-label="Permalink to &quot;개념&quot;">​</a></h1><h2 id="아키텍처" tabindex="-1">아키텍처 <a class="header-anchor" href="#아키텍처" aria-label="Permalink to &quot;아키텍처&quot;">​</a></h2><p>swag2mcp는 API 명세와 LLM 에이전트 간의 브리지 역할을 합니다:</p><img src="'+a+`" width="800" alt="swag2mcp architecture"><h2 id="핵심-개념" tabindex="-1">핵심 개념 <a class="header-anchor" href="#핵심-개념" aria-label="Permalink to &quot;핵심 개념&quot;">​</a></h2><p><strong>Spec</strong> — API 도메인 또는 서비스를 나타내는 논리적 컨테이너(예: YouTube, Binance, Open-Meteo). 각 spec은 고유한 <code>domain</code>, <code>base_url</code>, 선택적 <code>auth</code>를 가지며 하나 이상의 collection을 포함합니다. 또한 <code>llm_instruction</code>을 설정할 수 있습니다 — swag2mcp 시스템 프롬프트에 주입되어 LLM에 이 spec의 용도와 사용 시기를 알려주는 짧은 힌트입니다. 자세히 알아보기: <a href="./specs">Specs</a>.</p><p><strong>Collection</strong> — 특정 API를 설명하는 단일 OpenAPI/Swagger/Postman 파일입니다. <code>location</code>(URL 또는 로컬 파일 경로)을 가리킵니다. 하나의 spec은 여러 collection을 가질 수 있습니다 — 예를 들어, &quot;meteo&quot; spec에는 각각 다른 명세 파일을 가리키는 &quot;Forecast&quot;, &quot;Air Quality&quot;, &quot;Marine&quot; collection이 있을 수 있습니다. 자세히 알아보기: <a href="./collections">Collections</a>.</p><p><strong>Tag</strong> — collection 내 엔드포인트의 카테고리입니다. LLM이 올바른 작업을 더 정확하게 찾는 데 도움을 줍니다. 자세히 알아보기: <a href="./tags">Tags</a>.</p><p><strong>Endpoint</strong> — 특정 HTTP 메서드 + 경로(예: <code>GET /api/users</code>). LLM은 설명으로 엔드포인트를 찾고, 매개변수와 스키마를 검사한 후 호출할 수 있습니다. 자세히 알아보기: <a href="./endpoints">Endpoints</a>.</p><p><strong>Workspace</strong> — swag2mcp가 설정, 명세 캐시, 저장된 응답, 인증 스크립트를 저장하는 디렉토리입니다. 자세히 알아보기: <a href="./workspace">Workspace</a>.</p><h2 id="작동-방식" tabindex="-1">작동 방식 <a class="header-anchor" href="#작동-방식" aria-label="Permalink to &quot;작동 방식&quot;">​</a></h2><ol><li><p><strong>spec 또는 collection 추가</strong> — YAML 설정(<code>~/.swag2mcp/swag2mcp.yaml</code>)에 정의합니다. 예:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">specs</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">domain</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">jokes</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    llm_title</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Dad Joke API</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    base_url</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">https://icanhazdadjoke.com</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    collections</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">llm_title</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Jokes</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">        location</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">https://raw.githubusercontent.com/mmadfox/swag2mcp/main/specs/dadjoke.yaml</span></span></code></pre></div></li><li><p><strong>swag2mcp가 각 collection을 파싱</strong> — Tag와 Endpoint를 생성하고 검색을 위해 인덱싱합니다.</p></li><li><p><strong>LLM이 올바른 엔드포인트를 찾음</strong> — MCP 도구(<code>search</code>, <code>endpoint_by_tag</code>, <code>inspect</code>)를 통해 LLM이 설명과 일치하는 엔드포인트를 검색하고 매개변수와 요청 스키마를 검토합니다.</p></li><li><p><strong>LLM이 엔드포인트를 호출</strong> — MCP 도구 <code>invoke</code>를 통해 LLM이 요청을 보냅니다. swag2mcp는 호출 전에 엔드포인트의 OpenAPI 스키마에 대해 모든 입력 매개변수(path params, query params, headers, request body)를 검증합니다. 스키마와 일치하지 않으면 LLM은 무엇이 잘못되었는지 설명하는 명확한 오류를 받습니다. 검증이 완료되면 swag2mcp가 실제 HTTP 호출을 실행하고 결과를 반환합니다.</p></li><li><p><strong>결과가 LLM으로 돌아감</strong> — API 응답이 에이전트에 전달됩니다. 큰 응답은 워크스페이스에 저장되며 세 가지 전용 MCP 도구로 탐색할 수 있습니다: <code>response_outline</code>(구조 보기), <code>response_compress</code>(대표 샘플로 축소), <code>response_slice</code>(특정 조각 추출).</p></li></ol><p>swag2mcp는 LLM과 API 세계 간의 브리지입니다. API 명세를 추가하면 LLM이 MCP 프로토콜을 통해 올바른 엔드포인트를 찾고, 문서를 검사하고, 호출합니다. 여러분이 해야 할 일은 spec을 추가하고 MCP 서버를 시작하는 것뿐입니다.</p><blockquote><p><strong>설정은 언제든지 편집 가능합니다.</strong> YAML 설정 파일(<code>~/.swag2mcp/swag2mcp.yaml</code>)은 수동으로 편집할 수 있습니다 — spec 추가, 인증 변경, 설정 조정. 편집 후에는 변경 사항을 적용하려면 MCP 서버를 다시 시작하세요(<code>swag2mcp mcp</code>).</p></blockquote><h2 id="계층-구조" tabindex="-1">계층 구조 <a class="header-anchor" href="#계층-구조" aria-label="Permalink to &quot;계층 구조&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Spec (domain, e.g. &quot;meteo&quot;)</span></span>
<span class="line"><span>  └── Collection 1 (spec file, e.g. forecast.yml)</span></span>
<span class="line"><span>        └── Tag 1 (category)</span></span>
<span class="line"><span>              └── Endpoint (GET /api/forecast)</span></span>
<span class="line"><span>              └── Endpoint (POST /api/forecast)</span></span>
<span class="line"><span>        └── Tag 2</span></span>
<span class="line"><span>              └── Endpoint (GET /api/forecast/{id})</span></span>
<span class="line"><span>  └── Collection 2 (spec file, e.g. air-quality.yml)</span></span>
<span class="line"><span>        └── Tag 3</span></span>
<span class="line"><span>              └── Endpoint (GET /api/air-quality)</span></span></code></pre></div>`,16)])])}const E=e(t,[["render",o]]);export{m as __pageData,E as default};
